Tr.Begin();
int a = 5, b = 10, c = 15;
Tr.S("ثلاثة صناديق.", "a", a, "b", b, "c", c);
Tr.At(2, "نحسب كل مقارنة أولًا.", "a > b", a > b, "b < c", b < c, "c > 20", c > 20, "a == 5", a == 5);
Tr.At(2, "&& قبل ||: نحسب b < c && c > 20.", "b < c && c > 20", b < c && c > 20);
Tr.At(2, "ثم || من اليسار: False || False ثم || True.", "a > b || b < c && c > 20", a > b || b < c && c > 20, "… || a == 5", a > b || b < c && c > 20 || a == 5);
Console.WriteLine(a > b || b < c && c > 20 || a == 5);
Tr.S("الطباعة: True، يكفي طرف صحيح واحد مع ||.");
Tr.End();

Tr.Begin();
int m = 135;
Tr.S("135 دقيقة.", "m", m);
Tr.At(2, "القسمة الصحيحة: كم ساعة كاملة؟", "m / 60", m / 60);
Tr.At(2, "باقي القسمة: كم دقيقة بقيت؟", "m % 60", m % 60);
Console.WriteLine(m / 60 + ":" + m % 60);
Tr.S("الطباعة: 2:15.");
Tr.End();
